"""Detection engine package for Mini-IDS.

Contains rule-based detectors for identifying network security anomalies:
- PortScanDetector: Identifies TCP port scans (distinct destination ports).
- SynRateDetector: Identifies unusually high TCP SYN rates.
- TrafficAnomalyDetector: Identifies sudden surges in traffic byte or packet volume.
"""

from dataclasses import asdict, dataclass
from typing import Optional, Union


@dataclass
class Alert:
    """Structured security alert generated by detection rules.

    Attributes:
        timestamp (float): Timestamp when the alert was triggered (epoch seconds).
        rule_name (str): Identifier of the detection rule ('PORT_SCAN', 'SYN_RATE', 'TRAFFIC_VOLUME').
        src_ip (Optional[str]): Source IP address associated with the activity, if applicable.
        dst_ip (Optional[str]): Destination IP address associated with the activity, if applicable.
        observed_value (Union[int, float]): The observed metric value (e.g. port count, packet rate, bytes).
        threshold (Union[int, float]): The configured threshold that was crossed.
        window_seconds (float): Evaluation window duration in seconds.
        severity (str): Priority tier ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL').
        message (str): Human-readable summary describing the trigger condition.
    """

    timestamp: float
    rule_name: str
    src_ip: Optional[str]
    dst_ip: Optional[str]
    observed_value: Union[int, float]
    threshold: Union[int, float]
    window_seconds: float
    severity: str
    message: str
    detection_method: str = "HEURISTIC"
    model_version: Optional[str] = None
    confidence: Optional[float] = None
    anomaly_score: Optional[float] = None

    def to_dict(self) -> dict:
        """Convert the alert instance to a standard Python dictionary."""
        return asdict(self)


from detection.port_scan import PortScanDetector
from detection.syn_rate import SynRateDetector
from detection.traffic_anomaly import TrafficAnomalyDetector
from detection.hybrid_detection import HybridDetectionEngine

__all__ = [
    "Alert",
    "PortScanDetector",
    "SynRateDetector",
    "TrafficAnomalyDetector",
    "HybridDetectionEngine",
]
